/*
 * Which game build this is, and translation of the Steam-build RVAs the dll is written for (same scheme as
 * SWH2.Core GameBuild / ExeImage.Map). The build is told apart by the exe's PE timestamp (the Coop exe patch doesn't
 * change it); the GOG map is generated by tools/re/build_map.py. An unknown build is treated as Steam: every hook
 * still checks the bytes it replaces.
 */
#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include "netplay.h"

typedef struct { DWORD start, end; int delta; } MapRange;
#include "map_gog.h"

static const MapRange *map;   /* NULL = Steam (identity) */
static int mapLen;
static const char *buildName = "Steam";

void ExeMapInit(const char *exeBase)
{
    const IMAGE_NT_HEADERS *nt = (const IMAGE_NT_HEADERS *)(exeBase + ((const IMAGE_DOS_HEADER *)exeBase)->e_lfanew);
    if (nt->FileHeader.TimeDateStamp == MAP_GOG_STAMP)
    {
        map = map_gog;
        mapLen = (int)(sizeof map_gog / sizeof map_gog[0]);
        buildName = "GOG";
    }
}

const char *ExeBuildName(void) { return buildName; }

DWORD ExeRva(DWORD steamRva)
{
    if (!map) return steamRva;
    int lo = 0, hi = mapLen - 1;
    while (lo <= hi)
    {
        int mid = (lo + hi) / 2;
        if (steamRva < map[mid].start) hi = mid - 1;
        else if (steamRva >= map[mid].end) lo = mid + 1;
        else return (DWORD)((int)steamRva + map[mid].delta);
    }
    return 0;
}

DWORD SteamRva(DWORD rva)
{
    if (!map) return rva;
    for (int i = 0; i < mapLen; i++)
    {
        DWORD s = (DWORD)((int)rva - map[i].delta);
        if (s >= map[i].start && s < map[i].end) return s;
    }
    return 0;
}
